import NuevoProveedor from "../../../Componentes/Formularios/NuevoProveedor/NuevoProveedor";
import PestaniasConfiguraciones from "../../../Componentes/PestaniasConfiguraciones/PestaniasConfiguraciones";
import Boton from '../../../Componentes/Boton/Boton';
import Modal from '../../../Componentes/Modal/Modal';
import PlantillaConfiguraciones from '../../../Componentes/PlantillaConfiguraciones/PlantillaConfiguraciones';
import { useState, useEffect } from 'react';
import editar from '../../../assets/editar.png'
import mas from '../../../assets/mas.png'
import './Proveedores.css'
import ModificarProveedor from "../../../Componentes/Formularios/ModificarProveedor/ModificarProveedor";
import { useValidarSesion } from "../../../hooks/useValidarSesion";

export default function Proveedores() {


    //Recupero informacion del usuario logueado
    const { usuario } = useValidarSesion(); // obtener el token desde Zustand

    //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE crear proveedor
    const permisoCrearProveedor = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'crear proveedor'
    ) ||
        usuario?.permisos_extra?.some(
            (permiso) => permiso.nombrePermiso === 'crear proveedor'
        );

    ////////OBTENER LISTA DE PROVEEDORES
    const [proveedores, setProveedores] = useState([]);
    const obtenerDatos = () => {
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/proveedor`)
            .then(respuesta => respuesta.json())
            .then(datos => setProveedores(datos))
            .catch(e => console.log(e));
    }

    useEffect(() => {
        obtenerDatos();
    }, []);

    /////////MODAL NUEVO PROVEEDOR

    const [modalNuevoProveedor, setModalNuevoProveedor] = useState(false);
    const manejaModalNuevoProveedor = () => {
        if (modalNuevoProveedor) {
            obtenerDatos();
        }
        setModalNuevoProveedor(!modalNuevoProveedor);
    };

    ////////MODAL MODIFICA PROVEEDOR
    const [modalModificaProveedor, setModalModificaProveedor] = useState(false);
    const manejaModalModificaProveedor = () => {
        if (modalModificaProveedor) {
            obtenerDatos();
        }
        setModalModificaProveedor(!modalModificaProveedor);
    };

    //////MANEJA SELECCION
    const [seleccionado, setSeleccionado] = useState('');
    const manejaSeleccion = ({ id_proveedor, nombre, telefono, correo }) => {
        setSeleccionado({ id_proveedor, nombre, telefono, correo });
        manejaModalModificaProveedor();
    }
    console.log(seleccionado);

    /////////LAYOUT

    const navigation = <PestaniasConfiguraciones></PestaniasConfiguraciones>

    const main = <div className='__cuerpo_proveedores'>
        <div className='__cabecera_proveedores'>
            <h1>Proveedores</h1>
            {permisoCrearProveedor && <Boton icono={mas} habilitado onClick={manejaModalNuevoProveedor} title="Cargar nuevo proveedor"></Boton>}
        </div>
        <div className='__lista_proveedores'>
            {proveedores.map((item, index) => (
                <div className="__proveedor_item" key={index}>
                    {permisoCrearProveedor ? <span className='__proveedor_categoria'>{`${item.nombre} - ${item.telefono} - ${item.correo}`}</span> :
                        <span className='__proveedor_categoria' style={{ padding: "10px" }}>{`${item.nombre} - ${item.telefono} - ${item.correo}`}</span>}
                    {permisoCrearProveedor && <Boton icono={editar} habilitado onClick={() => manejaSeleccion({
                        id_proveedor: item.id_proveedor,
                        nombre: item.nombre,
                        telefono: item.telefono,
                        correo: item.correo
                    })} title="Editar proveedor"></Boton>}
                </div>

            ))}

        </div>
        <Modal visible={modalNuevoProveedor} funcion={manejaModalNuevoProveedor} titulo="Nuevo Proveedor" anchura="500px">
            <NuevoProveedor onGuardar={manejaModalNuevoProveedor}></NuevoProveedor>
        </Modal>
        <Modal visible={modalModificaProveedor} funcion={manejaModalModificaProveedor} titulo="Modificar Proveedor" anchura="500px">
            <ModificarProveedor onGuardar={manejaModalModificaProveedor} autocompletar={seleccionado}></ModificarProveedor>
        </Modal>


    </div>


    return <PlantillaConfiguraciones navigation={navigation} main={main} />;
}